def update_obs(observation):
    full_image = observation["observation"]["head_camera"]["rgb"]
    left_wrist_image = (
        observation["observation"].get("left_camera", {}).get("rgb", None)
    )
    right_wrist_image = (
        observation["observation"].get("right_camera", {}).get("rgb", None)
    )
    state = observation["joint_action"]["vector"]

    return {
        "full_image": full_image,
        "left_wrist_image": left_wrist_image,
        "right_wrist_image": right_wrist_image,
        "state": state,
    }

def _extract_obs_image(self, raw_obs):
    batch_images = []
    batch_wrist_images = []
    batch_states = []
    batch_instructions = []
    for obs in raw_obs:
        batch_images.append(
            self.center_and_crop(obs["full_image"], center_crop=self.center_crop)
        )
        wrist_images = []
        if "left_wrist_image" in obs and obs["left_wrist_image"] is not None:
            wrist_images.append(
                self.center_and_crop(
                    obs["left_wrist_image"], center_crop=self.center_crop
                )
            )
        if "right_wrist_image" in obs and obs["right_wrist_image"] is not None:
            wrist_images.append(
                self.center_and_crop(
                    obs["right_wrist_image"], center_crop=self.center_crop
                )
            )
        if len(wrist_images) > 0:
            batch_wrist_images.append(
                torch.stack([torch.from_numpy(img) for img in wrist_images])
            )
        batch_states.append(obs["state"])
        batch_instructions.append(obs["instruction"])

    batch_images = torch.stack([torch.from_numpy(img) for img in batch_images])
    if len(batch_wrist_images) > 0:
        batch_wrist_images = torch.stack(batch_wrist_images)
    else:
        batch_wrist_images = None
    batch_states = torch.stack([torch.from_numpy(state) for state in batch_states])

    extracted_obs = {
        "main_images": batch_images,
        "wrist_images": batch_wrist_images,
        "states": batch_states,
        "task_descriptions": batch_instructions,
    }

    return extracted_obs

def _select_configured_state(self, states):
    """Select a configured subset of the raw env state (openpi parity)."""
    indices = self.state_indices
    if not indices:
        return states

def env_obs_to_observation(self, env_obs: dict[str, Any]) -> Observation:
    """Repack env obs through the transform pipeline onto this device."""
    self._ensure_transforms()
    repacked = repack_env_obs(
        self.config_name,
        env_obs,
        select_state=self._select_configured_state,
    )
    processed = self.input_transform(repacked, transpose=False)
    return self._observation_dict_to_device(processed)
